CREATE TABLE checkins(id TEXT PRIMARY KEY,student TEXT NOT NULL,day TEXT NOT NULL,app TEXT NOT NULL DEFAULT '',words INTEGER NOT NULL DEFAULT 0,minutes INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',images TEXT NOT NULL DEFAULT '[]',comment TEXT NOT NULL DEFAULT '',seen INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL,updated TEXT NOT NULL,UNIQUE(student,day));
CREATE INDEX idx_checkins_student ON checkins(student,day);
